/**
 * Spin: rotates the object continuously.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Ticker } from "pixi.js";
import { Component, isEditorPaused } from "../core";

export interface SpinParams {
  /** Turns per second. Negative spins the other way. */
  speed: number;
}

/** Rotates the object continuously. Paused in Edit mode — switch to Play to preview. */
export class Spin extends Component<SpinParams> {
  static readonly componentName = "Spin";
  static readonly defaults: SpinParams = { speed: 0.25 };

  private time = 0;
  private applied = 0;
  private written = NaN;

  update(): void {
    this.reset();
    if (isEditorPaused()) return;
    this.time += Ticker.shared.deltaMS / 1000;
    this.applied =
      (this.time * this.params.speed * Math.PI * 2) % (Math.PI * 2);
    this.target.rotation += this.applied;
    this.written = this.target.rotation;
  }

  detach(): void {
    this.reset();
  }

  /** Removes last frame's rotation offset, unless something else changed it since. */
  private reset(): void {
    if (this.applied !== 0 && this.target.rotation === this.written)
      this.target.rotation -= this.applied;
    this.applied = 0;
  }
}
